"""PlatformIO pre-build script for crowpanel21-mapbench: turns the recorded chunk sets in
docs/fixtures/map/chunks into bench/generated/map_chunks.cpp (gitignored), so the bench
firmware carries them. Release builds never include this."""

from pathlib import Path

Import("env")  # noqa: F821  (PlatformIO's SCons global)

PROJECT = Path(env.subst("$PROJECT_DIR"))  # noqa: F821
SOURCE = PROJECT.parent / "docs" / "fixtures" / "map" / "chunks"
OUT = PROJECT / "bench" / "generated" / "map_chunks.cpp"

files = sorted(SOURCE.glob("*/*.bin"))
lines = [
    "// Generated by bench/embed_chunks.py from docs/fixtures/map/chunks. Do not edit.",
    "// Data (c) OpenStreetMap contributors (ODbL), tiles (c) OpenMapTiles via OpenFreeMap.",
    '#include "map_bench_scene.h"',
    "",
    "namespace {",
]
for i, f in enumerate(files):
    data = f.read_bytes()
    body = ",".join(str(b) for b in data)
    lines.append(f"// {f.parent.name}/{f.name}")
    lines.append(f"const uint8_t kChunk{i}[] = {{{body}}};")
lines.append("}  // namespace")
lines.append("")
lines.append("extern const sarathi::bench::ChunkBlob kBenchChunks[] = {")
lines += [f"    {{kChunk{i}, sizeof(kChunk{i})}}," for i in range(len(files))]
lines.append("};")
lines.append(f"extern const size_t kBenchChunkCount = {len(files)};")
text = "\n".join(lines) + "\n"
OUT.parent.mkdir(exist_ok=True)
if not OUT.exists() or OUT.read_text() != text:
    OUT.write_text(text)
print(f"embed_chunks: {len(files)} chunks -> {OUT.relative_to(PROJECT)}")
